    return (Array.isArray(services) ? services : [])
      .filter((r) => r.bookable === true || String(r.bookable || '').trim().toLowerCase() === 'yes')
      .map((r) => String(r.service || '').trim().toLowerCase())
      .filter(Boolean);
  }

