  // Escapes customer text so it cannot trigger mentions (<!channel>) or disguised links.
  function escapeForSlack(text) {
    if (text === null || text === undefined) return '';
    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
